import re
import json
import sys
import os

def parse_script(text):
    # Split text into sections by [NodeID]
    # We use re.split with a capturing group to keep the IDs
    pattern = r'\[([^\]]+)\]'
    parts = re.split(pattern, text)
    # parts will be [prefix, id1, content1, id2, content2, ...]

    nodes_dict = {}
    edges = []
    first_node_id = None

    # Process identified nodes
    for i in range(1, len(parts), 2):
        node_id = parts[i].strip()
        content = parts[i+1].strip()

        if first_node_id is None:
            first_node_id = node_id

        lines = [l.strip() for l in content.split('\n') if l.strip()]

        # Check if it is a choice node
        is_choice = any(re.match(r'^\d+\.', l) for l in lines)

        if is_choice:
            nodes_dict[node_id] = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            }
            for line in lines:
                # Match "1. Text -> Target"
                m = re.match(r'^\d+\.\s*(.*?)\s*->\s*([a-zA-Z0-9_]+)$', line)
                if not m:
                    # Fallback for targets with other characters
                    m = re.match(r'^\d+\.\s*(.*?)\s*->\s*(\S+)$', line)
                if m:
                    edge_text = m.group(1).strip()
                    target = m.group(2).strip()
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": edge_text
                    })
        else:
            # Line node
            if lines:
                line = lines[0]
                if '->' in line:
                    parts_transition = line.rsplit('->', 1)
                    target = parts_transition[1].strip()
                    content_before = parts_transition[0].strip()

                    if ':' in content_before:
                        speaker, text_content = content_before.split(':', 1)
                        speaker = speaker.strip()
                        text_content = text_content.strip()
                    else:
                        speaker = ""
                        text_content = content_before

                    nodes_dict[node_id] = {
                        "id": node_id,
                        "text": text_content,
                        "speaker": speaker,
                        "type": "line"
                    }
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": ""
                    })
                else:
                    # Node without transition in the same line
                    nodes_dict[node_id] = {
                        "id": node_id,
                        "text": line,
                        "speaker": "",
                        "type": "line"
                    }
            else:
                # Empty node
                nodes_dict[node_id] = {
                    "id": node_id,
                    "text": "",
                    "speaker": "",
                    "type": "line"
                }

    # Handle referenced nodes that are not explicitly defined in [NodeID]
    referenced_targets = set(e['to'] for e in edges)
    for target in referenced_targets:
        if target not in nodes_dict:
            nodes_dict[target] = {
                "id": target,
                "text": "",
                "speaker": "",
                "type": "line"
            }

    # Constraint (1): Reachability from the first node
    reachable_nodes = set()
    if first_node_id:
        stack = [first_node_id]
        while stack:
            curr = stack.pop()
            if curr not in reachable_nodes:
                reachable_nodes.add(curr)
                for edge in edges:
                    if edge['from'] == curr:
                        stack.append(edge['to'])

    # Filter nodes and edges based on reachability
    # Maintain original order of definition
    defined_order = []
    for match in re.finditer(pattern, text):
        nid = match.group(1).strip()
        if nid not in defined_order:
            defined_order.append(nid)

    # Add undefined but reachable nodes (like 'End') to the order
    for target in sorted(referenced_targets):
        if target not in defined_order:
            defined_order.append(target)

    final_nodes = []
    for nid in defined_order:
        if nid in reachable_nodes and nid in nodes_dict:
            final_nodes.append(nodes_dict[nid])

    final_edges = [e for e in edges if e['from'] in reachable_nodes]

    return {"nodes": final_nodes, "edges": final_edges}

def to_dot(graph):
    dot = ["digraph dialogue {"]
    dot.append('  node [shape=box];')
    for node in graph['nodes']:
        # Construct label for visualization
        if node['speaker'] and node['text']:
            label = f"{node['speaker']}: {node['text']}"
        elif node['text']:
            label = node['text']
        else:
            label = node['id']

        # Escape quotes for DOT
        label = label.replace('"', '\\"')
        dot.append(f'  "{node["id"]}" [label="{label}"];')

    for edge in graph['edges']:
        label = edge['text'].replace('"', '\\"')
        dot.append(f'  "{edge["from"]}" -> "{edge["to"]}" [label="{label}"];')

    dot.append("}")
    return "\n".join(dot)

if __name__ == "__main__":
    script_path = "/app/script.txt"
    if os.path.exists(script_path):
        with open(script_path, "r") as f:
            content = f.read()

        graph = parse_script(content)

        # Output JSON
        with open("/app/dialogue.json", "w") as f:
            json.dump(graph, f, indent=2)

        # Output DOT
        dot_content = to_dot(graph)
        with open("/app/dialogue.dot", "w") as f:
            f.write(dot_content)

